package local.mediacenter.library
import org.json.*
import org.junit.Test
import org.junit.Assert.*
class JellyfinOfflineProgressPlanTest {
 private val id="1".repeat(32)
 private fun manifest(kind:String="movie")=JSONObject().put("id",id).put("key","video:key").put("source","original").put("item",JSONObject().put("kind",kind).put("duration",120.0))
 private fun remote(type:String="Movie")=JSONObject().put("Id",id).put("Type",type).put("RunTimeTicks",1200000000L).put("MediaSources",JSONArray().put(JSONObject().put("Id","original"))).put("UserData",JSONObject().put("PlaybackPositionTicks",412500000L).put("Played",false).put("PlayCount",2).put("LastPlayedDate","old"))
 @Test fun movieAndEpisodeProgressUsesExactVideoVersion(){assertEquals(41.25,JellyfinOfflineProgressPlan.remote(remote(),manifest()).getDouble("currentTime"),.0001);assertFalse(JellyfinOfflineProgressPlan.remote(remote("Episode"),manifest("videoEpisode")).getBoolean("isFinished"));for(raw in listOf(remote("Audio"),remote().put("Id","2".repeat(32)),remote().put("RunTimeTicks",1300000000L),remote().put("MediaSources",JSONArray())))assertTrue(runCatching{JellyfinOfflineProgressPlan.remote(raw,manifest())}.isFailure)}
 @Test fun checkpointBelongsToTheCachedVersionAndExplicitMediaKind(){val m=manifest();val point=JSONObject().put("offline",true).put("source","original").put("kind","movie").put("duration",120).put("position",30);assertEquals(30.0,JellyfinOfflineProgressPlan.checkpoint(point,m),.001);for(change in listOf(JSONObject(point.toString()).put("source","old"),JSONObject(point.toString()).put("kind","videoEpisode"),JSONObject(point.toString()).put("duration",80),JSONObject(point.toString()).put("offline",false),JSONObject().put("position",30)))assertTrue(runCatching{JellyfinOfflineProgressPlan.checkpoint(change,m)}.isFailure)}
 @Test fun unknownCompletionAndInvalidPositionsAreNotGuessed(){for(data in listOf(JSONObject().put("PlaybackPositionTicks",1),JSONObject().put("PlaybackPositionTicks",-1).put("Played",false),JSONObject().put("PlaybackPositionTicks",2000000000L).put("Played",false)))assertTrue(runCatching{JellyfinOfflineProgressPlan.remote(remote().put("UserData",data),manifest())}.isFailure)}
 @Test fun stoppedReportHasNoInventedSessionOrTimeDelta(){val body=JellyfinOfflineProgressPlan.payload(manifest(),41.25);assertEquals(412500000L,body.getLong("PositionTicks"));assertEquals(setOf("ItemId","MediaSourceId","PositionTicks","Failed"),body.keys().asSequence().toSet());assertTrue(runCatching{JellyfinOfflineProgressPlan.payload(manifest(),121.5)}.isFailure)}
 @Test fun revisionChangesWithServerPositionCompletionCredentialsAndLocalCheckpoint(){val a=JSONObject().put("id","source").put("url","https://server").put("userId",id).put("accessToken","secret");val m=manifest();val server=JellyfinOfflineProgressPlan.remote(remote(),m);val original=JellyfinOfflineProgressPlan.revision(a,m,"local",server);assertNotEquals(original,JellyfinOfflineProgressPlan.revision(a,m,"new-local",server));for(value in listOf(JSONObject(server.toString()).put("currentTime",50.0),JSONObject(server.toString()).put("isFinished",true),JSONObject(server.toString()).put("lastPlayed","new")))assertNotEquals(original,JellyfinOfflineProgressPlan.revision(a,m,"local",value));assertNotEquals(original,JellyfinOfflineProgressPlan.revision(JSONObject(a.toString()).put("accessToken","other"),m,"local",server))}
}
